import{_ as l,a0 as p,w as o,s as d,ao as c,I as t,x as i,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 RHEL 8 上安裝 MiniKube | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 8 上安裝 MiniKube | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 8 上安裝 MiniKube | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 8 上安裝 MiniKube | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230308.2 ⭐️⭐️ How to Install MiniKube on RHEL 8Rocky Linux 8AlmaLinux 8","title":"如何在 RHEL 8 上安裝 MiniKube","tag":"202303","desc":""},"relativePath":"202303/20230308.2 ⭐️⭐️ How to Install MiniKube on RHEL 8Rocky Linux 8AlmaLinux 8.md","filePath":"[post].md"}'),r={name:"202303/20230308.2 ⭐️⭐️ How to Install MiniKube on RHEL 8Rocky Linux 8AlmaLinux 8.md"};function u(h,s,k,b,g,m){const e=p("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-rhel-8-上安裝-minikube" tabindex="-1">如何在 RHEL 8 上安裝 MiniKube <a class="header-anchor" href="#如何在-rhel-8-上安裝-minikube" aria-label="Permalink to “如何在 RHEL 8 上安裝 MiniKube”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/15/232024hn8312yg1qmy7mhv.jpg" alt=""></p><blockquote><p>在這篇文章中，我們將逐步介紹如何在 RHEL 8、Rocky Linux 8 或 AlmaLinux 8 上安裝 MiniKube。</p></blockquote><p>MiniKube 是一個跨平台的開源工具，可以讓你在本地機器上部署單節點 Kubernetes 集羣。</p><p>Kubernetes，也被稱為 k8s，或簡稱 Kube，是一個開源的容器編排平台，用於容器的自動化擴展和部署。MiniKube 集羣幫助開發人員和管理員在集羣中構建他們的測試環境。</p><h5 id="minikube-的先決條件" tabindex="-1">MiniKube 的先決條件 <a class="header-anchor" href="#minikube-的先決條件" aria-label="Permalink to “MiniKube 的先決條件”">​</a></h5><ul><li>最小化安裝的 RHEL 8 或 Rocky Linux 8 或 AlmaLinux 8</li><li>本地配置的 RHEL 8 倉庫或訂閲</li><li>至少 2GB RAM 和 2 個 vCPU</li><li>20GB 硬盤空間</li><li>具有管理員身份的 sudo 用户</li><li>穩定的互聯網連接</li><li>Docker 或虛擬機管理器，如 VirtualBox、KVM 和 VMware 等</li></ul><p>在這篇文章中，我們將使用 Docker 作為 MiniKube 的驅動程序。滿足所有先決條件後，現在是時候捲起袖子動手了。</p><h3 id="步驟-1-啓用官方-docker-倉庫" tabindex="-1">步驟 1）啓用官方 Docker 倉庫 <a class="header-anchor" href="#步驟-1-啓用官方-docker-倉庫" aria-label="Permalink to “步驟 1）啓用官方 Docker 倉庫”">​</a></h3><p>要啓用 Docker 官方倉庫，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf config-manager --add-repo=https://download.docker.com/linux/centos/docker-ce.repo</span></span>
<span class="line"><span>$ sudo dnf repolist</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Enable-Docker-Repo-RHEL8-Rocky-Linux8-1024x203.png" alt=""></p><h3 id="步驟-2-安裝-docker-ce-社區版" tabindex="-1">步驟 2）安裝 Docker CE（社區版） <a class="header-anchor" href="#步驟-2-安裝-docker-ce-社區版" aria-label="Permalink to “步驟 2）安裝 Docker CE（社區版）”">​</a></h3><p>運行以下 <code>dnf</code> 命令來安裝 Docker 及其依賴項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install docker-ce docker-ce-cli containerd.io -y</span></span></code></pre></div><p>輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Install-Docker-DNF-Command-RHEL8-RockyLinux8.png" alt=""></p><p>安裝 Docker 後啓動並啓用它的服務，運行以下 <code>systemctl</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start docker</span></span>
<span class="line"><span>$ sudo systemctl start docker</span></span></code></pre></div><p>允許你的本地用户在沒有 <code>sudo</code> 的情況下運行 <code>docker</code> 命令，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -aG docker $USER</span></span>
<span class="line"><span>$ newgrp docker</span></span></code></pre></div><h3 id="步驟-3-安裝-kubectl-二進制文件" tabindex="-1">步驟 3）安裝 kubectl 二進制文件 <a class="header-anchor" href="#步驟-3-安裝-kubectl-二進制文件" aria-label="Permalink to “步驟 3）安裝 kubectl 二進制文件”">​</a></h3><p><code>kubectl</code> 是一個命令列工具，它通過 API 與 Kubernetes 集羣進行交互。我們使用 <code>kubectl</code> 部署應用。默認情況下，<code>kubectl</code> 不包含在 RHEL 8 、Rocky Linux 8 或 AlmaLinux 8 軟件包倉庫中。因此，我們將使用下面的命令手動安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -LO &quot;https://dl.k8s.io/release/$(curl -L -s https://dl.k8s.io/release/stable.txt)/bin/linux/amd64/kubectl&quot;</span></span>
<span class="line"><span>$ sudo cp kubectl /usr/local/bin/ &amp;&amp; sudo chmod +x /usr/local/bin/kubectl</span></span>
<span class="line"><span>$ kubectl version --client</span></span></code></pre></div><p>以上命令的輸出如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Download-Kubectl-Binary-RHEL8-RockyLinux8.png" alt=""></p><h3 id="步驟-4-下載-minikube-二進制文件並啓動集羣" tabindex="-1">步驟 4）下載 MiniKube 二進制文件並啓動集羣 <a class="header-anchor" href="#步驟-4-下載-minikube-二進制文件並啓動集羣" aria-label="Permalink to “步驟 4）下載 MiniKube 二進制文件並啓動集羣”">​</a></h3><p>安裝 <code>kubectl</code> 後，讓我們使用以下命令下載並安裝 MiniKube 二進制文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -LO https://storage.googleapis.com/minikube/releases/latest/minikube-linux-amd64</span></span>
<span class="line"><span>$ sudo install minikube-linux-amd64 /usr/local/bin/minikube</span></span></code></pre></div><p>現在使用下面的命令啓動 MiniKube 集羣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube start --driver docker</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Start-Minikube-Cluster-RHEL8-Rocky-Linux8.png" alt=""></p><p>上面的輸出確認 <code>minikube</code> 命令已經使用 <code>docker</code> 作為驅動程序啓動了單節點 Kubernetes 集羣。</p><p>運行下面的 <code>minikube</code> 命令來驗證本地 Kubernetes 集羣的狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube status</span></span>
<span class="line"><span>minikube</span></span>
<span class="line"><span>type: Control Plane</span></span>
<span class="line"><span>host: Running</span></span>
<span class="line"><span>kubelet: Running</span></span>
<span class="line"><span>apiserver: Running</span></span>
<span class="line"><span>kubeconfig: Configured</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ minikube ip</span></span>
<span class="line"><span>192.168.49.2</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>要停止 MiniKube 集羣，請執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube stop</span></span></code></pre></div><p>執行 <code>kubectl</code> 命令查看集羣和節點信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl cluster-info</span></span>
<span class="line"><span>$ kubectl get nodes</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/K8s-cluster-info-RHEL8-RockyLinux9-1024x193.png" alt=""></p><h3 id="步驟-5-測試和驗證-kubernetes-集羣" tabindex="-1">步驟 5）測試和驗證 Kubernetes 集羣 <a class="header-anchor" href="#步驟-5-測試和驗證-kubernetes-集羣" aria-label="Permalink to “步驟 5）測試和驗證 Kubernetes 集羣”">​</a></h3><p>為了測試 Kubernetes 集羣，讓我們嘗試使用 echo 服務器鏡像創建 k8s 部署，它相當於 HTTP Web 服務器並將其作為服務暴露在端口 8080 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create deployment test-minikube --image=k8s.gcr.io/echoserver:1.10</span></span>
<span class="line"><span>deployment.apps/test-minikube created</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>要訪問 <code>test-minikube</code> 部署，將其公開為服務，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl expose deployment test-minikube --type=NodePort --port=8080</span></span>
<span class="line"><span>service/test-minikube exposed</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>運行以下 <code>kubectl</code> 命令以獲取上面創建的部署、<ruby>容器莢<rt>pod</rt></ruby> 和服務信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get deployment,pods,svc</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Kubectl-get-pods-deplyments-service-rhel8-rocky-linux8.png" alt=""></p><p>要訪問服務，請通過運行下面的命令獲取其 URL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube service test-minikube --url</span></span>
<span class="line"><span>http://192.168.49.2:32291</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ curl http://192.168.49.2:32291/</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Access-Application-minikube-rhel8-rockylinux8.png" alt=""></p><p>太好了，這意味着我們的 Kubernetes 集羣工作正常，因為我們能夠訪問我們的示例應用。</p><h5 id="步驟-6-啓用-minikube-插件" tabindex="-1">步驟 6）啓用 MiniKube 插件 <a class="header-anchor" href="#步驟-6-啓用-minikube-插件" aria-label="Permalink to “步驟 6）啓用 MiniKube 插件”">​</a></h5><p>MiniKube 提供插件，可以為我們的集羣添加額外的功能。要列出所有可用的插件，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube addons list</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/minikube-addons-list-rhel8-rockylinux8.png" alt=""></p><p>Kubernetes 附帶一個儀表板，可讓你管理集羣。在 MiniKube 中，儀表板已作為插件添加。所以要啓用它，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube addons enable dashboard</span></span></code></pre></div><p>還要啓用 nginx 入口控制器，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube addons enable ingress</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Enable-Minikube-addons-RHEL8-RockyLinux9-1024x381.png" alt=""></p><p>要訪問儀表板，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ minikube dashbaord --url</span></span></code></pre></div><p>這將在你係統的瀏覽器中啓動儀表板。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2020/04/Kubernetes-Dashboard-MiniKube-Dashboard.png" alt=""></p><p>就是這些了。我們已經成功地在 RHEL 8、Rocky Linux 8 或 AlmaLinux 8 上使用 MiniKube 安裝了 Kubernetes。歡迎你在下面的評論部分分享你的反饋和意見。</p><hr>`,67)),t("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.linuxtechi.com/install-minikube-on-rhel-rockylinux-almalinux/"},{default:n(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/install-minikube-on-rhel-rockylinux-almalinux/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=i("作者：",-1)),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[2]||(s[2]=[i("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),a(e,{href:"https://github.com/lkxed/"},{default:n(()=>[...s[3]||(s[3]=[i("lkxed",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const w=l(r,[["render",u]]);export{y as __pageData,w as default};
